BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
R=[['希腊 dráō / drân','做、行动、表演']]
DG=R+[['希腊 drâma，词干 dramat-','做出的行动；戏剧作品']]
D=DG+[['后期拉丁 drama → 英语 drama','戏剧；充满波折的事件']]
DT=DG+[['希腊 dramatikós → 后期拉丁 dramaticus → 英语 dramatic','戏剧的；有强烈效果、引人注目的']]
