W=[
E('drama','英 /ˈdrɑːmə/；美 /ˈdrɑːmə/','戏剧；剧情作品；戏剧性事件；夸张纷争','把人物的行动和冲突演出来，而不只是平铺直叙地讲。','经后期拉丁 drama 借希腊 drâma“行动、戏剧”，接 dráō“做、表演”。相关词常保留 dramat- 词干，所以 dramatic 中的 t 不是随便插入的。',D,'study drama 是学习戏剧；a television drama 是电视剧。日常说 too much drama，也可能是在抱怨事情被闹得太激烈，不是真的在说舞台表演。','a television drama；study drama；the drama of an event；unnecessary drama。','drama 是作品类型或冲突场面；dramatic 是形容词。中文“有戏剧性”不一定表示事情虚构。',('She studied drama before becoming a teacher.','她当老师之前学过戏剧。'),('The series is a family drama set in a small coastal town.','这部剧讲述发生在海滨小镇的家庭故事。'),('The lost keys caused more drama than the journey itself.','丢钥匙引起的那阵折腾，比旅程本身还热闹。'),sources=['https://www.etymonline.com/word/drama']),
E('dramatic','/drəˈmætɪk/','戏剧的；显著、惊人的；夸张激烈的','像舞台上的关键一幕，变化或表现让人一下注意到。','经后期拉丁 dramaticus 借希腊 dramatikós，来自 drâma 的 dramat- 词干；不是现代 drama 简单加 -ic 的完整历史。',DT,'a dramatic increase 是增长很明显；a dramatic performance 是戏剧表演或富有感染力的表现；a dramatic reaction 还可能批评反应夸张。由所修饰的词判断。','a dramatic change；a dramatic increase；dramatic arts；a dramatic gesture。','drastic 更强调措施猛烈或变化幅度很大；dramatic 还可强调显眼、引人注目，不一定严厉。',('The new timetable led to a dramatic reduction in waiting times.','新的时刻表让等候时间明显缩短。'),('She has considerable dramatic talent.','她很有戏剧表演天赋。'),('He made a dramatic gesture towards the exit.','他夸张地朝出口做了个手势。'),sources=['https://www.etymonline.com/word/dramatic']),
E('dramatically','/drəˈmætɪkli/','显著地；大幅地；富有戏剧性地','变化一下很明显，或者动作表情像在表演关键场面。','dramatic 加 -ally；-ically 通常压缩读作 /ɪkli/。保留形容词的戏剧表演与显著变化两条常用义。',DT+[['英语 dramatic + -ally → dramatically','以引人注目、富有戏剧性的方式']],'prices rose dramatically 表示价格大幅上涨，不是“价格在演戏”；pause dramatically 则真在描述刻意制造效果的停顿。','change dramatically；increase dramatically；pause dramatically。','significantly 常表示变化有意义或幅度明显；dramatically 更强调醒目、强烈的效果，统计语境不能自动等同“显著性检验通过”。',('Energy use fell dramatically after the renovation.','改造后，能源消耗大幅下降。'),('The actor paused dramatically before revealing the secret.','演员在揭露秘密前作了一个富有戏剧性的停顿。'),sources=['https://en.wiktionary.org/wiki/dramatically#English']),
E('drastic','/ˈdræstɪk/','激烈的；严厉的；幅度极大的','不是轻轻调一下，而是下重手、作很大改变。','接希腊 drastikós“有强效的”，源于 dráō“做”。早期英语用于强力药物，后来扩展到力度大的措施和变化，不是 drama 的缩写。',DS,'drastic measures 是力度很大的措施，往往因为问题严重才采用；a drastic cut 是大幅削减，可能影响很深。它通常比 small adjustment 强得多。','drastic measures；a drastic cut；a drastic change。','dramatic 侧重引人注目；drastic 侧重猛烈、极端或改动很大，常带需要慎重权衡的感觉。',('The company took drastic measures to reduce its debt.','公司采取了力度很大的措施来减少债务。'),('A drastic cut in staff would affect the quality of the service.','大幅裁减人员会影响服务质量。'),sources=['https://www.etymonline.com/word/drastic']),
E('drastically','/ˈdræstɪkli/','大幅度地；剧烈地；彻底地','变化的幅度很大，原来的状况被明显改写了。','drastic 加 -ally，形成说明改变力度的副词。',DS+[['英语 drastic + -ally → drastically','以大幅、激烈的方式']],'reduce costs drastically 是大幅削减成本；change drastically 可以是制度、生活或环境发生重大改变，不只表示速度快。','reduce drastically；change drastically；differ drastically。','rapidly 说快；drastically 说变动大。变化可以很快但幅度小，也可以长期逐渐累积成重大差别。',('The new process drastically reduced the amount of waste.','新流程大幅减少了废料。'),('Their plans changed drastically when the venue closed.','场地关闭后，他们的计划发生了重大改变。'),sources=['https://en.wiktionary.org/wiki/drastically#English']),
E('dramatics','/drəˈmætɪks/','戏剧活动、表演；故作夸张的情绪表现','可以是在舞台上表演，也可以是在生活中把反应弄得像演戏。','由 dramatic 接 -s / -ics 形成活动名词。戏剧活动义常作为整体概念；夸张行为义则常像在说一连串做作的表现。',DT+[['英语 dramatic + -s → dramatics','戏剧表演活动；夸张的动作情绪']],'amateur dramatics 是业余戏剧活动；enough dramatics 则常是让对方别再故作激动。后者带批评，不能用来轻率否定真实痛苦。','amateur dramatics；school dramatics；unnecessary dramatics。','drama 可指一部剧；dramatics 通常说戏剧活动或夸张表现，不用 a dramatics 指一部作品。',('She became involved in amateur dramatics at university.','她在大学参加了业余戏剧活动。'),('The team solved the problem without any unnecessary dramatics.','团队平静地解决了问题，没有多余的夸张反应。'),sources=['https://en.wiktionary.org/wiki/dramatics#English']),
E('dramatist','/ˈdræmətɪst/','剧作家','用人物对话和行动，把故事写成可供演出的作品。','采用 drama 的希腊词干 dramat- 加 -ist，表示从事戏剧创作的人。虽然 drama 常读 /drɑːmə/，这里常见 /dræ-/。',D+[['英语 dramat- + -ist → dramatist','创作戏剧的人']],'指写剧本的人，不是因为会演戏就叫 dramatist。可用于舞台剧，也可用于广播或电视剧本作者。','a leading dramatist；a television dramatist；a contemporary dramatist。','actor 表演角色；dramatist 创作剧本。playwright 与 dramatist 意思非常接近。',('The festival invited a young dramatist to discuss her first play.','戏剧节邀请一位年轻剧作家谈她的首部作品。'),('He worked as a radio dramatist for many years.','他当了多年广播剧作家。'),sources=['https://www.etymonline.com/word/dramatist','https://www.oxfordlearnersdictionaries.com/definition/english/dramatist']),
E('dramatize','/ˈdræmətaɪz/','改编为戏剧、影视作品；戏剧化、夸大','把叙述变成角色行动，或者把小事表现得像重大戏剧冲突。','采用 drama 的 dramat- 词干加 -ize，英语里造出动词。t 来自希腊名词的词干变化，不是“多出一个字母”就表示更强烈。',D+[['英语 dramat- + -ize → dramatize','改编演出；强调、夸张地表现']],'dramatize a novel 是改编小说；dramatize a minor problem 则是把小问题渲染得很严重。也可中性地说用故事生动显示某问题。','dramatize a novel；dramatize an event；dramatize a problem。','adapt 范围更广，包含为用途作各种改编；dramatize 特别与戏剧、戏剧化表达有关。',('The novel was dramatized for television.','这部小说被改编成了电视剧。'),('The article dramatizes a minor disagreement as a major crisis.','文章把一次小分歧渲染成了重大危机。'),sources=['https://www.etymonline.com/word/dramatize','https://www.oxfordlearnersdictionaries.com/definition/english/dramatize']),
E('dramatise','/ˈdræmətaɪz/','改编成戏剧或影视；戏剧化处理','把故事做成可表演的情节，或让叙述显得更惊心动魄。','dramatize 的常见英式拼法，-ise 与 -ize 在这里表达同一个动词后缀。两种拼写不改变读音与基本意思。',D+[['英语 dramat- + -ise → dramatise','dramatize 的拼写变体']],'英国出版物里常见 dramatise a story。一个词换了拼写，并不意味着改编一定更忠实，也不表示只能上舞台不能拍电影。','dramatise a story；dramatise real events；dramatise the issue。','dramatise 与 dramatize 主要是拼写选择；dramatist 是写戏的人，不是这个动词的另一形式。',('The theatre group will dramatise a local legend.','剧团将把一个当地传说改编成戏。'),('The documentary uses actors to dramatise key events.','纪录片使用演员重现关键事件。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/dramatize']),
E('dramatization','英 /ˌdræmətaɪˈzeɪʃən/；美 /ˌdræmətəˈzeɪʃən/','戏剧化改编；改编作品；戏剧化表现','原本是文字或发生过的事情，现在被组织成可观看的场景。','dramatize 加 -ation，表示改编过程或改编出的作品。英式也常写 dramatization / dramatisation，基本意义相同。',D+[['英语 dramatize + -ation → dramatization','戏剧化改编及其成品']],'a dramatization of a trial 是用演员和场景重现审判；它可能据事实改编，也可能调整细节，所以不等于现场录像。','a dramatization of；a television dramatization；a stage dramatization。','documentary 以纪录为主；dramatization 明确包含表演和情节组织，两种形式也可能结合。',('The programme includes a dramatization of the rescue.','节目包含对救援过程的戏剧化重现。'),('She preferred the novel to its television dramatization.','相比电视改编版，她更喜欢原著小说。'),sources=['https://www.etymonline.com/word/dramatization','https://www.oxfordlearnersdictionaries.com/definition/english/dramatization']),
E('melodrama','英 /ˈmelədrɑːmə/；美 /ˈmelədrɑːmə/','情节煽情的戏剧；夸张的感情冲突','冲突和情绪被放大，让人紧张、落泪或强烈站队。','借法语 mélodrame，由来自希腊 mélos“歌曲”的 mélo- 与法语 drame 结合；原先是配音乐的戏剧，后来音乐不再是必要条件，重点转向煽情和强烈情节。',MD,'文学史里的 melodrama 是一种戏剧传统；日常 no need for melodrama 则是在批评情绪被夸大。不要仅按词根译成“音乐剧”，现代 musical 是另一种常用分类。','a Victorian melodrama；a touch of melodrama；avoid melodrama。','drama 范围广；melodrama 通常突出强烈的情绪、曲折或煽情，语气是否贬义取决于语境。',('The film turns a simple family dispute into melodrama.','电影把一个简单的家庭争执拍成了煽情冲突。'),('The class studied a nineteenth-century melodrama.','课堂研究了一部十九世纪的情节剧。'),sources=['https://www.etymonline.com/word/melodrama']),
E('melodramatic','英 /ˌmelədrəˈmætɪk/；美 /ˌmelədrəˈmætɪk/','情节剧式的；过分激动、煽情的','情绪和反应被推得很满，像随时要上演重大转折。','由 melodrama 按 dramatic 的形式造出形容词；不是每次都把 mélo- 理解成现场配乐。',MD+[['英语 melodrama → melodramatic，仿 dramatic','情节剧式；煽情、夸张的']],'a melodramatic ending 常是结尾过分煽情；a melodramatic reaction 常批评反应比实际情形更激烈。讨论戏剧风格时也可中性使用。','a melodramatic scene；a melodramatic reaction；melodramatic dialogue。','dramatic 可只是显著、有感染力；melodramatic 更容易带过度煽情、夸张的评价。',('The final scene felt melodramatic rather than moving.','最后一幕让人觉得煽情过头，并不感人。'),('He gave a melodramatic sigh when the printer ran out of paper.','打印机没纸时，他夸张地长叹了一口气。'),sources=['https://www.etymonline.com/word/melodramatic']),
E('overdramatic','英 /ˌəʊvədrəˈmætɪk/；美 /ˌoʊvərdrəˈmætɪk/','过于戏剧化的；反应夸张的','事情本没有那么严重，表现却像一场大灾难。','over-“过度” + dramatic，明确加上超过合适程度的评价。',DT+[['英语 over- + dramatic → overdramatic','戏剧性或情绪反应过度的']],'常修饰表演、语气或反应。它表达说话人的评价，不是客观量表；在评论真实感受时要留意语气。','an overdramatic reaction；an overdramatic performance；sound overdramatic。','melodramatic 常带煽情风格；overdramatic 直接强调过了头，不必属于某种戏剧类型。',('The director asked for a quieter, less overdramatic performance.','导演要求表演收敛些，不要那么夸张。'),('Calling the minor delay a disaster sounded overdramatic.','把这点小延误叫作灾难，听起来太夸张了。'),sources=['https://en.wiktionary.org/wiki/overdramatic#English'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0343')
shared={'dramaturgy'};excluded={'monodrama':'按用户最新范围暂略：较专门的独角戏体裁术语。'}
ROOT=[dict(id='C0343',meaning='做；行动；表演',core='dra-：做出行动；行动被演成戏剧，也能成为强烈有效的作用。',image='drama 是演出的行动；dramatic 是像戏剧般引人注目；drastic 则走向力度大、作用强。',intro='来自希腊 dráō“做、表演”。戏剧分支通过 drâma 发展，常保留 dramat- 词干；drastic 来自另一形容词 drastikós，不是 dramatic 的缩写。',forms='drama 的相关希腊词干为 dramat-，所以 dramatist、dramatize 带 t。dramatic 有戏剧、显著、夸张几种常用义；melodrama 原与配乐相关，现代不等于所有音乐剧。',branches=[['戏剧作品与创作','drama、dramatist、dramatics、dramatize、dramatise、dramatization、dramaturgy'],['醒目、夸张与煽情','dramatic、dramatically、melodrama、melodramatic、overdramatic'],['强烈作用与大幅变化','drastic、drastically']],contrasts='dramatic 强调显眼、效果强；drastic 强调力度大、变化激烈。dramatize 可以中性说改编，也可批评夸大；看它的宾语和情境。',practice='分别写一次 dramatic improvement 和一项 drastic measure，说明前者强调结果引人注目，后者强调手段力度大。',words=[k for k in family if k not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/drama','https://www.etymonline.com/word/drastic','https://www.etymonline.com/word/melodrama'])]
assert {x['word'] for x in W}==set(family)-shared-set(excluded)
assert len(W)==len({x['word'] for x in W}) and all(x['word'] in m['owned_words'] for x in W)
for x in W:
 assert len(x['examples'])>=2 and x['ipa'] and len(x['history'])>=2,x['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in x['history']),x['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_71_dra.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0343',len(W),'new',len(ROOT[0]['words']),'references',sum(len(x['examples']) for x in W),'examples')
